#!/usr/bin/env node
/* The custom mood slots: the one place their model lives (tables, option texts, seeds), and the
   writer of the two files made from it:
     - ha/packages/moods/moods_custom.yaml (the whole file), and
     - the six slot subviews in ha/dashboards/palm_moods.yaml, between the marker comments
       "# >>> generated by ui/dev/gen-custom.js" and "# <<< generated".
   Never edit either by hand: change this file, then run `node ui/dev/gen-custom.js --write`.

   usage: node ui/dev/gen-custom.js            compare both files with what this would write; prints
                                               the first difference and exits 1 if anything differs
          node ui/dev/gen-custom.js --write    write them
   lint.js runs the same comparison. The option texts are frozen in ui/dev/custom-options.lock.json:
   a slot that has an option chosen keeps it only while that exact text exists (after a restart a
   missing option falls back to the first one, and a step silently becomes "No step"), so lint fails
   when one is renamed or removed. To add an option, append it here and to the lock file.

   Module API (for lint.js, and for sim.js / fake-ha.js / drive.js on the phone side):
     SLOTS, STEPS, TABLES, WHERE, SEED_START, SEED_CLEAR, BUILTIN_SLUGS, helperIds(n),
     options(), packageYaml(), dashboardBlock(), dashboardWith(text), check(), MARK_START, MARK_END
   Runs on Node 24 with no npm packages. */
'use strict';
const fs = require('fs');
const path = require('path');
const { loadMoods } = require('./mood-yaml');

const ROOT = path.join(__dirname, '..', '..');
const PKG = path.join(ROOT, 'ha', 'packages', 'moods');
const PKG_FILE = path.join(PKG, 'moods_custom.yaml');
const DASH_FILE = path.join(ROOT, 'ha', 'dashboards', 'palm_moods.yaml');
const MARK_START = '  # >>> generated by ui/dev/gen-custom.js';
const MARK_END = '  # <<< generated';

const SLOTS = 6;
const STEPS = 4;

/* ---- the tables ---------------------------------------------------------------------------- */
// label -> [role entity, touch label, room (card scope), outdoor 0/1]. No guest room, no all_lights.
const ROLES = {
  'Bedroom lamps': ['light.role_bedroom_lamps', 'Lamps', 'Bedroom', 0],
  'Bedroom movie lamp': ['light.role_bedroom_movie_lamp', 'Lamp', 'Bedroom', 0],
  'Office lights': ['light.role_office_lights', 'Office', 'Office', 0],
  'Loft lamp': ['light.role_loft_lamp', 'Loft', 'Loft', 0],
  'Living room lights': ['light.role_living_room_lights', 'Living', 'Living room', 0],
  'Kitchen lights': ['light.role_kitchen_lights', 'Kitchen', 'Kitchen', 0],
  'Patio lights': ['light.role_patio_lights', 'Patio', 'Outdoors', 1],
  'Porch lights': ['light.role_porch_lights', 'Porch', 'Outdoors', 1],
  'Driveway lights': ['light.role_driveway_lights', 'Drive', 'Outdoors', 1]
};
// "Turn other indoor lights off"
const INDOOR = ['light.role_bedroom_lamps', 'light.role_office_lights', 'light.role_loft_lamp', 'light.role_living_room_lights', 'light.role_kitchen_lights'];
// label -> [kind, arg]: white (kelvin), colour ([r, g, b]), keep (brightness only), off
const DO = {
  'Soft white (2700 K)': ['white', 2700],
  'Warm white (2200 K)': ['white', 2200],
  'Candlelight (2000 K)': ['white', 2000],
  'Neutral white (4000 K)': ['white', 4000],
  'Daylight (5000 K)': ['white', 5000],
  'Cool daylight (6500 K)': ['white', 6500],
  'Amber': ['colour', [255, 140, 40]],
  'Deep red': ['colour', [150, 8, 6]],
  'Rose': ['colour', [255, 90, 120]],
  'Magenta': ['colour', [220, 40, 160]],
  'Violet': ['colour', [120, 60, 220]],
  'Blue': ['colour', [40, 80, 255]],
  'Teal': ['colour', [20, 170, 160]],
  'Green': ['colour', [60, 200, 80]],
  'Keep its colour': ['keep', 0],
  'Off': ['off', 0]
};
const GLYPHS = { 'Ember': 'ember', 'Candle': 'candle', 'Curtain': 'curtain', 'Bulbs': 'bulbs', 'Moon': 'moon', 'Sunrise': 'sunrise', 'Desk lamp': 'desk_lamp', 'Glasses': 'glasses', 'Key': 'key' };
// dashboard only
const GLYPH_ICON = { ember: 'mdi:fire', candle: 'mdi:candle', curtain: 'mdi:curtains', bulbs: 'mdi:lightbulb-group', moon: 'mdi:weather-night', sunrise: 'mdi:weather-sunset-up', desk_lamp: 'mdi:desk-lamp', glasses: 'mdi:glasses', key: 'mdi:key-variant' };
// preset -> the built-in mood whose palette it copies (base, glows, accent and ink; never its sky)
const PALETTE_FROM = [['Ember amber', 'wind_down'], ['Cinema red', 'movie_night'], ['Dusk rose', 'afterglow'], ['Night indigo', 'lights_out'], ['Sunrise gold', 'good_morning'], ['Daylight blue', 'focus'], ['Garden brass', 'hosting'], ['Steel night', 'away']];
const PALETTE_NEW = {
  'Ocean teal': { base: '#04090c', glows: ['#1f7a86', '#123e5a', '#5a4a7a'], accent: '#7cc9cf' },
  'Forest green': { base: '#060a05', glows: ['#5f8a3a', '#2c4a26', '#7a5a2a'], accent: '#a9cf7c' }
};
// label -> [from, to] (local time, from inclusive, to exclusive). "Any time" is absent: no window.
const WINDOWS = {
  'Mornings (05:00 to 11:00)': ['05:00', '11:00'],
  'Daytime (08:00 to 18:00)': ['08:00', '18:00'],
  'Evenings (17:00 to 23:00)': ['17:00', '23:00'],
  'Late evening (20:00 to 02:00)': ['20:00', '02:00'],
  'Night (21:00 to 07:00)': ['21:00', '07:00']
};
const FADE = { 'Usual (2 s)': 2, 'Instant': 0, 'Slow (10 s)': 10, 'Very slow (30 s)': 30 };
const OTHERS = { 'Leave other lights alone': 'leave', 'Turn other indoor lights off': 'indoor', 'Turn every other light off, outdoors too': 'all' };
const TV = { 'Leave the TV alone': null, 'Bedroom TV on': 'on', 'Bedroom TV off': 'off' };
const SCENT = { 'Leave the diffuser alone': null, 'Diffuser on': 'on', 'Diffuser off': 'off' };
const BED = { "Bed off": 'off', "Bed to 62 °F": 62, "Bed to 64 °F": 64, "Bed to 66 °F": 66, "Bed to 68 °F": 68, "Bed to 70 °F": 70 };
const BED_LEAVE = 'Leave the bed alone';
const NO_STEP = 'No step';
// placement, for every mood (built-in and slot); read by the phones by exact text
const WHERE = ['Usual (as the mood says)', 'First on every phone', 'Only on the Bedroom Palm', 'Only on the Living room Palm', 'Not on the Bedroom Palm', 'Not on the Living room Palm', 'Hidden on every phone'];

function palettes() {
  const moods = loadMoods(PKG);
  const out = {};
  PALETTE_FROM.forEach(([label, slug]) => {
    const m = moods.find((x) => x.entity_id === 'script.mood_' + slug);
    const p = m && m.attributes.mood_palette;
    if (!p || typeof p !== 'object') throw new Error('gen-custom: no mood_palette in script.mood_' + slug + ' for "' + label + '"');
    const o = { base: p.base, glows: p.glows, accent: p.accent };
    if (p.ink) o.ink = p.ink;
    out[label] = o;
  });
  Object.keys(PALETTE_NEW).forEach((k) => { out[k] = PALETTE_NEW[k]; });
  return out;
}
const PALETTES = palettes();
const BUILTIN_SLUGS = loadMoods(PKG).map((m) => m.entity_id.replace(/^script\.mood_/, ''));
const TABLES = { ROLES, INDOOR, DO, GLYPHS, GLYPH_ICON, PALETTES, WINDOWS, FADE, OTHERS, TV, SCENT, BED, BED_LEAVE, NO_STEP };

/* ---- the helpers of one slot --------------------------------------------------------------- */
// the option lists, first = default (what a new helper, and one whose option vanished, reads)
function options() {
  return {
    glyph: Object.keys(GLYPHS),
    colours: Object.keys(PALETTES),
    window: ['Any time'].concat(Object.keys(WINDOWS)),
    fade: Object.keys(FADE),
    others: Object.keys(OTHERS),
    tv: Object.keys(TV),
    scent: Object.keys(SCENT),
    bed: [BED_LEAVE].concat(Object.keys(BED)),
    step_lights: [NO_STEP].concat(Object.keys(ROLES)),
    step_do: Object.keys(DO),
    where: WHERE.slice()
  };
}
function helperIds(n) {
  const p = 'custom_mood_' + n + '_';
  const steps = [];
  for (let k = 1; k <= STEPS; k++) steps.push({ lights: 'input_select.' + p + 'step_' + k + '_lights', do: 'input_select.' + p + 'step_' + k + '_do', pct: 'input_number.' + p + 'step_' + k + '_pct' });
  return {
    on: 'input_boolean.' + p + 'on', night: 'input_boolean.' + p + 'night',
    name: 'input_text.' + p + 'name', tagline: 'input_text.' + p + 'tagline',
    glyph: 'input_select.' + p + 'glyph', colours: 'input_select.' + p + 'colours', window: 'input_select.' + p + 'window',
    fade: 'input_select.' + p + 'fade', others: 'input_select.' + p + 'others',
    tv: 'input_select.' + p + 'tv', scent: 'input_select.' + p + 'scent', bed: 'input_select.' + p + 'bed',
    steps,
    where: 'input_select.moods_custom_' + n + '_where', order: 'input_number.moods_custom_' + n + '_order',
    sensor: 'sensor.moods_custom_' + n, script: 'script.mood_custom_' + n, slug: 'custom_' + n
  };
}
// Start and Clear write these (Clear: an empty name and no step 1; Start: a draft, switched off)
function seed(start) {
  const o = options();
  const s = {
    name: start ? 'New mood' : '', tagline: '', glyph: o.glyph[0], colours: o.colours[0], window: o.window[0], night: false,
    fade: o.fade[0], others: o.others[0], tv: o.tv[0], scent: o.scent[0], bed: o.bed[0], on: false, where: WHERE[0], order: 0, steps: []
  };
  for (let k = 1; k <= STEPS; k++) s.steps.push({ lights: NO_STEP, do: o.step_do[0], pct: 50 });
  if (start) s.steps[0] = { lights: 'Bedroom lamps', do: 'Soft white (2700 K)', pct: 40 };
  return s;
}
const SEED_START = seed(true);
const SEED_CLEAR = seed(false);

/* ---- a tiny YAML writer (block style; strings quoted unless plainly safe) ------------------ */
const block = (s) => ({ __block: s });
const flow = (v) => ({ __flow: v });
const RESERVED = /^(y|yes|n|no|on|off|true|false|null|~)$/i;
function scalar(v) {
  if (v === null) return 'null';
  if (typeof v === 'boolean' || typeof v === 'number') return String(v);
  const s = String(v);
  if (/^[A-Za-z_/][A-Za-z0-9_.:/-]*$/.test(s) && !RESERVED.test(s) && !/:$/.test(s)) return s;
  return JSON.stringify(s);
}
function jflow(v) {   // a flow value: JSON with double-quoted strings (valid YAML)
  return JSON.stringify(v, null, 0).replace(/,(?=["\d[{-])/g, ', ').replace(/":(?=\S)/g, '": ');
}
function emit(obj, ind) {
  const pad = ' '.repeat(ind);
  const out = [];
  Object.keys(obj).forEach((k) => {
    const v = obj[k];
    if (k[0] === '#') { String(v).split('\n').forEach((l) => out.push(pad + '#' + (l ? ' ' + l : ''))); return; }
    out.push.apply(out, emitKV(pad + k + ':', v, ind));
  });
  return out;
}
function emitKV(head, v, ind) {
  if (v && v.__block !== undefined) return [head + ' |-'].concat(v.__block.split('\n').map((l) => (l ? ' '.repeat(ind + 2) + l : '')));
  if (v && v.__flow !== undefined) return [head + ' ' + jflow(v.__flow)];
  if (Array.isArray(v)) {
    if (!v.length) return [head + ' []'];
    return [head].concat(emitList(v, ind + 2));
  }
  if (v && typeof v === 'object') return [head].concat(emit(v, ind + 2));
  if (typeof v === 'string' && /\n/.test(v)) return emitKV(head, block(v), ind);
  return [head + ' ' + scalar(v)];
}
function emitList(arr, ind) {
  const pad = ' '.repeat(ind);
  const out = [];
  arr.forEach((item) => {
    if (item && typeof item === 'object' && !Array.isArray(item) && item.__block === undefined && item.__flow === undefined) {
      const lines = emit(item, ind + 2);
      // the first non-comment line of the item goes on the "- " line
      const first = lines.findIndex((l) => !/^\s*#/.test(l));
      for (let i = 0; i < first; i++) lines[i] = pad + lines[i].trim();
      lines[first] = pad + '- ' + lines[first].slice(ind + 2);
      out.push.apply(out, lines);
    } else if (item && item.__flow !== undefined) out.push(pad + '- ' + jflow(item.__flow));
    else out.push(pad + '- ' + (typeof item === 'string' ? JSON.stringify(item) : scalar(item)));   // list strings always quoted
  });
  return out;
}

/* ---- the card template (one per slot; the same body in `state` and `attributes.card`) ------- */
function tbl(name, v) { return "{%- set " + name + " = " + jflow(v) + " %}"; }
const BAD_J = "['', 'unknown', 'unavailable']";
/* Jinja: true when slot n holds anything a mood does (switched on, card text, any step with lights,
   other lights, an extra). Read from the slot's helpers by explicit id, the same rule the card uses
   for "empty" (a blank name alone never makes a slot empty), so the sensor's name and Start agree. */
function usedExpr(n) {
  const h = helperIds(n), o = options();
  const q = (a) => jflow(a);
  return [
    "is_state('" + h.on + "', 'on')",
    "(states('" + h.tagline + "') | replace('|', ' ') | trim) not in " + BAD_J
  ].concat(h.steps.map((s) => "states('" + s.lights + "') not in " + q([NO_STEP].concat(['', 'unknown', 'unavailable']))))
    .concat([
      "states('" + h.others + "') in " + q(o.others.filter((k) => OTHERS[k] !== 'leave')),
      "states('" + h.tv + "') in " + q(o.tv.filter((k) => TV[k] !== null)),
      "states('" + h.scent + "') in " + q(o.scent.filter((k) => SCENT[k] !== null)),
      "states('" + h.bed + "') in " + q(Object.keys(BED))
    ]).join('\n   or ');
}
// the select fields whose unknown text falls back to a default: [helper suffix, dashboard label, options]
function checkedFields() {
  const o = options();
  return [['glyph', 'Picture', o.glyph], ['colours', 'Colours', o.colours], ['window', 'When it runs', o.window], ['others', 'Other lights', o.others],
    ['fade', 'Fade', o.fade], ['tv', 'Bedroom TV', o.tv], ['scent', 'Diffuser', o.scent], ['bed', "The bed", o.bed]];
}
function cardBody(n) {
  const p = 'custom_mood_' + n + '_';
  const bed = {}; Object.keys(BED).forEach((k) => { bed[k] = BED[k]; });
  return [
    "{%- set N = " + n + " %}{%- set p = '" + p + "' %}",
    tbl('ROLES', ROLES),
    tbl('DO', DO),
    tbl('GLYPHS', GLYPHS),
    tbl('PALETTES', PALETTES),
    tbl('WINDOWS', WINDOWS),
    tbl('FADE', FADE),
    tbl('OTHERS', OTHERS),
    tbl('BED', bed),
    "{%- set BAD = ['', 'unknown', 'unavailable'] %}",
    "{%- set name = states('input_text.' ~ p ~ 'name') | replace('|', ' ') | trim %}{%- set name = '' if name in BAD else name[:32] %}",
    "{%- set tag = states('input_text.' ~ p ~ 'tagline') | replace('|', ' ') | trim %}{%- set tag = '' if tag in BAD else tag[:120] %}",
    "{%- set fade = FADE.get(states('input_select.' ~ p ~ 'fade'), 2) %}",
    "{%- set others = OTHERS.get(states('input_select.' ~ p ~ 'others'), 'leave') %}",
    "{%- set s = namespace(steps=[], words=[], touches=[], rooms=[], problems=[], outdoor=false, offs=[], used=false) %}",
    "{%- for k in range(1, " + (STEPS + 1) + ") %}",
    "  {%- set l = states('input_select.' ~ p ~ 'step_' ~ k ~ '_lights') %}",
    "  {%- set d = states('input_select.' ~ p ~ 'step_' ~ k ~ '_do') %}",
    "  {%- set pct = states('input_number.' ~ p ~ 'step_' ~ k ~ '_pct') | int(0) %}",
    "  {%- if l not in ['" + NO_STEP + "'] + BAD %}{%- set s.used = true %}{%- endif %}",
    "  {%- if l in ROLES and d in DO %}",
    "    {%- set e = ROLES[l][0] %}{%- set kind = DO[d][0] %}",
    "    {%- set members = state_attr(e, 'entity_id') %}",
    "    {%- if kind != 'off' and not (1 <= pct <= 100) %}",
    "      {%- set s.problems = s.problems + ['Step ' ~ k ~ ': brightness must be 1 to 100%, so it is skipped.'] %}",
    "    {%- else %}",
    "      {%- set s.steps = s.steps + [{'lights': l, 'do': d, 'pct': pct}] %}",
    "      {%- set s.words = s.words + [l ~ (' off' if kind == 'off' else ' ' ~ (d[:1] | lower) ~ d[1:] ~ ', ' ~ pct ~ '%')] %}",
    "      {%- set s.rooms = s.rooms + [ROLES[l][2]] %}",
    "      {%- if members is not iterable or members is string or members | count == 0 %}",
    "        {%- set s.problems = s.problems + ['Step ' ~ k ~ ': ' ~ l ~ ' has no lights yet, so it does nothing.'] %}",
    "      {%- elif kind == 'off' %}{%- set s.offs = s.offs + [[ROLES[l][1], e]] %}",
    "      {%- elif e not in (s.touches | map(attribute='entity') | list) %}",
    "        {%- set s.touches = s.touches + [{'label': ROLES[l][1], 'entity': e, 'expect': 'on'}] %}",
    "      {%- endif %}",
    "      {%- if kind != 'off' and ROLES[l][3] == 1 %}{%- set s.outdoor = true %}{%- endif %}",
    "    {%- endif %}",
    "  {%- elif l not in ['" + NO_STEP + "'] + BAD %}",
    "    {%- set s.problems = s.problems + ['Step ' ~ k ~ ': not understood, so it is skipped.'] %}",
    "  {%- endif %}",
    "{%- endfor %}",
    "{%- set tv = {'Bedroom TV on': 'on', 'Bedroom TV off': 'off'}.get(states('input_select.' ~ p ~ 'tv')) %}",
    "{%- set scent = {'Diffuser on': 'on', 'Diffuser off': 'off'}.get(states('input_select.' ~ p ~ 'scent')) %}",
    "{%- set bed = BED.get(states('input_select.' ~ p ~ 'bed')) %}",
    "{#- text that is not one of a field's options (only input_select.set_options can put it there) -#}",
    "{%- for f in " + jflow(checkedFields()) + " %}",
    "  {%- if states('input_select.' ~ p ~ f[0]) not in f[2] + BAD %}",
    "    {%- set s.problems = s.problems + [f[1] ~ ': not understood, so it uses ' ~ f[2][0] ~ '.'] %}",
    "  {%- endif %}",
    "{%- endfor %}",
    "{#- an \"off\" mark only when the fade is quick enough for the phone's 8 s mark window -#}",
    "{%- if s.touches | count == 0 and s.offs | count > 0 and fade <= 2 %}",
    "  {%- set s.touches = [{'label': s.offs[0][0], 'entity': s.offs[0][1], 'expect': 'off'}] %}",
    "{%- endif %}",
    "{%- if tv is not none %}{%- set s.touches = s.touches + [{'label': 'TV', 'entity': 'binary_sensor.role_bedroom_tv', 'expect': tv}] %}{%- endif %}",
    "{%- if scent is not none %}{%- set s.touches = s.touches + [{'label': 'Scent', 'entity': 'switch.role_diffuser', 'expect': scent}] %}{%- endif %}",
    "{%- if bed is number %}{%- set s.touches = s.touches + [{'label': 'Bed', 'entity': 'binary_sensor.role_bed', 'expect': 'on'}] %}",
    "{%- elif bed == 'off' %}{%- set s.touches = s.touches + [{'label': 'Bed', 'entity': 'binary_sensor.role_bed', 'expect': 'off'}] %}{%- endif %}",
    "{%- set actions = s.steps | count + ([tv, scent, bed] | reject('none') | list | count) + (0 if others == 'leave' else 1) %}",
    "{%- set on = is_state('input_boolean.' ~ p ~ 'on', 'on') %}",
    "{#- empty: nothing in it at all. A blank name alone never empties a slot (Start would wipe it) -#}",
    "{%- set used = on or tag != '' or s.used or actions > 0 %}",
    "{%- set st = 'empty' if not used else ('ready' if on and actions > 0 else 'not_ready') %}",
    "{%- set shown = name or 'Custom mood ' ~ N %}",
    "{%- if used and name == '' %}{%- set s.problems = s.problems + ['It has no name, so it shows as ' ~ shown ~ '.'] %}{%- endif %}",
    "{%- set reason = '' if st == 'ready' else ('That custom mood was cleared on the Moods dashboard.' if st == 'empty'",
    "      else (shown ~ ' is switched off on the Moods dashboard.' if not on else shown ~ ' has nothing to do yet.')) %}",
    "{%- set summary = (s.words",
    "      + ([] if others == 'leave' else (['Other indoor lights off'] if others == 'indoor' else ['Every other light off']))",
    "      + ([] if tv is none else ['Bedroom TV ' ~ tv]) + ([] if scent is none else ['Diffuser ' ~ scent])",
    "      + ([] if bed is none else (['Bed off'] if bed == 'off' else ['Bed to ' ~ bed ~ ' °F']))) | join('. ') %}",
    "{%- set w = WINDOWS.get(states('input_select.' ~ p ~ 'window')) %}",
    "{%- set rooms = s.rooms | unique | list %}",
    "{%- set card = {",
    "      'mood': st == 'ready', 'mood_slot': N, 'mood_state': st, 'mood_reason': reason,",
    "      'mood_name': shown, 'mood_tagline': tag or ((summary ~ '.') if summary else 'Nothing set yet.')[:120],",
    "      'mood_status': (s.words | first | default(''))[:40],",
    "      'mood_scope': rooms[0] if rooms | count == 1 else 'House',",
    "      'mood_glyph': GLYPHS.get(states('input_select.' ~ p ~ 'glyph'), 'ember'),",
    "      'mood_palette': PALETTES.get(states('input_select.' ~ p ~ 'colours'), PALETTES['Ember amber']),",
    "      'mood_night': is_state('input_boolean.' ~ p ~ 'night', 'on'),",
    "      'mood_window': none if w is none else {'from': w[0], 'to': w[1]},",
    "      'mood_order': 100 + 10 * N, 'mood_panels': [],",
    "      'mood_touches': s.touches[:5], 'mood_lights_outdoor': s.outdoor,",
    "      'mood_steps': s.steps,",
    "      'mood_extras': {'tv': tv, 'scent': scent, 'bed': bed, 'others': others, 'fade': fade},",
    "      'mood_summary': summary, 'mood_problems': s.problems } %}"
  ].join('\n');
}
function cardName(n) {
  const p = 'custom_mood_' + n + '_';
  return [
    "{%- set n = states('input_text." + p + "name') | replace('|', ' ') | trim %}",
    "{%- set n = '' if n in " + BAD_J + " else n[:32] %}",
    "{%- if n == '' and not (" + usedExpr(n) + ") %}Custom mood " + n + " (empty)",
    "{%- else %}{%- set n = n or 'Custom mood " + n + "' %}",
    "{%- if not is_state('input_boolean." + p + "on', 'on') %}{{ n }} (switched off)",
    // Home Assistant reads a rendered name that looks like a Python literal as one: "None" or
    // "[1]" would fail its name check, and "1.50" would show as 1.5. A zero-width space after such
    // a name keeps it text (the card's mood_name is unaffected: it lives inside the card dict).
    "{%- elif n[:1] in ['[', '{', '('] or n is match('^(none|true|false|[-+]?[0-9.][0-9._]*)$', ignorecase=true) %}{{ n ~ '\\u200b' }}",
    "{%- else %}{{ n }}{% endif %}",
    "{%- endif %}"
  ].join('\n');
}

/* ---- moods_custom.yaml --------------------------------------------------------------------- */
const HEADER = `# Palm Moods: the six custom mood slots, made and edited on the "Moods"
# dashboard (My moods tab).
#
# GENERATED by ui/dev/gen-custom.js. Do not edit: change the generator and run
# \`node ui/dev/gen-custom.js --write\`. ui/dev/lint.js fails if this file differs.
#
# What is here, per slot n = 1..6 (slug custom_n):
#   - the slot's helpers (custom_mood_n_*): what the dashboard edits. None has
#     \`initial:\`, so each keeps its value across restarts;
#   - its placement helpers (input_select.moods_custom_n_where and
#     input_number.moods_custom_n_order), read by the phones like those of the
#     built-in moods in moods_settings.yaml;
#   - sensor.moods_custom_n: state ready, not_ready or empty, and one attribute,
#     \`card\`: the mood's card (the same keys as a built-in mood's customize
#     attributes) plus the parsed steps. The phones, mood_begin, the runner, the
#     01:00 outdoor automation and the dashboard all read it. The template reads
#     only entities it names, never a whole domain, and every read has a default,
#     so garbage in a helper gives a default and a problem line, never an error;
#   - script.mood_custom_n: a real mood script. It runs mood_begin first, like
#     every mood (vacation, time window, newest wins, Undo), then awaits the runner;
#   and once:
#   - script.moods_custom_run: does what the card's steps say, mapping each option
#     text through its own fixed tables (no helper text ever becomes an entity id
#     or an action). Refuses unless its own slot script is running and is the
#     current mood, vacation mode is off and the card is ready;
#     It also records in input_text.custom_mood_lit_outdoor whether the run lit
#     an outdoor role, for the 01:00 outdoor-off;
#   - script.moods_custom_start / script.moods_custom_clear: fill a slot that
#     has nothing in it with a draft, or wipe one;
#   - the automation with YAML id moods_custom_save_soon (Home Assistant names it
#     automation.moods_save_dashboard_moods_soon_after_an_edit, from its alias):
#     saves restore state 10 s after the last edit, so a crash loses seconds of
#     dashboard edits, not up to 15 minutes.
#
# A custom mood can only change the lights of the Moods rooms, the bedroom TV,
# the diffuser and the bed (off, or 62 to 70 °F, through the clamped
# wrapper). It never touches the guest room, the thermostat or a speaker.`;

function helpersFor(n) {
  const o = options();
  const p = 'custom_mood_' + n + '_';
  const L = 'Custom mood ' + n + ': ';
  const ib = {}, it = {}, is = {}, inum = {};
  ib[p + 'on'] = { name: L + 'switched on', icon: 'mdi:toggle-switch-outline' };
  ib[p + 'night'] = { name: L + 'night face', icon: 'mdi:weather-night' };
  it[p + 'name'] = { name: L + 'name', icon: 'mdi:form-textbox', max: 32 };
  it[p + 'tagline'] = { name: L + 'card text', icon: 'mdi:text-short', max: 120 };
  const sel = (k, name, icon, opts) => { is[p + k] = { name: L + name, icon, options: opts }; };
  sel('glyph', 'picture', 'mdi:shape-outline', o.glyph);
  sel('colours', 'colours', 'mdi:palette', o.colours);
  sel('window', 'when it runs', 'mdi:clock-outline', o.window);
  sel('fade', 'fade', 'mdi:transition', o.fade);
  sel('others', 'other lights', 'mdi:lightbulb-group-off-outline', o.others);
  sel('tv', 'bedroom TV', 'mdi:television', o.tv);
  sel('scent', 'diffuser', 'mdi:scent', o.scent);
  sel('bed', 'bed', 'mdi:bed-outline', o.bed);
  for (let k = 1; k <= STEPS; k++) {
    sel('step_' + k + '_lights', 'step ' + k + ' lights', 'mdi:lightbulb-outline', o.step_lights);
    sel('step_' + k + '_do', 'step ' + k + ' make them', 'mdi:palette-outline', o.step_do);
    inum[p + 'step_' + k + '_pct'] = { name: L + 'step ' + k + ' brightness', icon: 'mdi:brightness-6', min: 1, max: 100, step: 1, mode: 'slider', unit_of_measurement: '%' };
  }
  is['moods_custom_' + n + '_where'] = { name: L + 'where it shows', icon: 'mdi:cellphone-cog', options: o.where };
  inum['moods_custom_' + n + '_order'] = { name: L + 'order in the deck (0 = usual)', icon: 'mdi:sort-numeric-ascending', min: 0, max: 999, step: 1, mode: 'box' };
  return { ib, it, is, inum };
}

function sensorFor(n) {
  const body = cardBody(n);
  const h = helperIds(n);
  const icons = {}; Object.keys(GLYPHS).forEach((k) => { icons[k] = GLYPH_ICON[GLYPHS[k]]; });
  return {
    unique_id: 'moods_custom_' + n,
    default_entity_id: 'sensor.moods_custom_' + n,
    '#': 'The picture chosen for the card, once the slot has a name (the icon is not a\ncapability: changing it never writes the entity registry).',
    icon: block("{%- set n = states('" + h.name + "') | trim %}\n{{- 'mdi:palette-swatch-outline' if n in " + BAD_J + " else " + jflow(icons) + ".get(states('" + h.glyph + "'), 'mdi:fire') }}"),
    name: block(cardName(n)),
    state: block(body + '\n{{- card.mood_state }}'),
    attributes: { card: block(body + '\n{{- card }}') }
  };
}

function slotScript(n) {
  return {
    alias: 'Mood: Custom ' + n,
    icon: 'mdi:palette-swatch-outline',
    mode: 'restart',
    sequence: [
      { '#': 'Keep these two steps first, as in every mood.', action: 'script.mood_begin', data: { slug: "{{ this.entity_id | replace('script.mood_', '') }}" }, response_variable: 'begin' },
      { condition: 'template', value_template: '{{ begin is mapping and begin.proceed | default(false) }}' },
      { '#': 'Awaited, not script.turn_on: when mood_begin stops this script for a newer\nmood, the runner is stopped with it.', action: 'script.moods_custom_run', data: { slot: "{{ this.entity_id | replace('script.mood_custom_', '') | int(0) }}" }, continue_on_error: true }
    ]
  };
}

const LIT_OUTDOOR = 'input_text.custom_mood_lit_outdoor';
function runner() {
  const roles = {}; Object.keys(ROLES).forEach((k) => { roles[k] = ROLES[k][0]; });
  const outdoor = Object.keys(ROLES).filter((k) => ROLES[k][3] === 1).map((k) => ROLES[k][0]);
  const ifThen = (cond, then) => ({ if: [{ condition: 'template', value_template: cond }], then });
  const lightOn = (data) => ({ action: 'light.turn_on', target: { entity_id: '{{ repeat.item.e }}' }, data, continue_on_error: true });
  return {
    alias: 'Moods: run a custom mood',
    description: 'Runs the steps of the custom mood that is current. Called only by script.mood_custom_<n> after mood_begin accepted it.',
    icon: 'mdi:playlist-play',
    mode: 'parallel',
    max: 10,
    fields: { slot: { name: 'Slot', required: true, selector: { number: { min: 1, max: SLOTS } } } },
    sequence: [
      {
        '#': 'Tables and limits live inside the sequence, so caller data cannot override them.',
        variables: {
          ROLES: flow(roles),
          DO: flow(DO),
          INDOOR: flow(INDOOR),
          OUTDOOR: flow(outdoor),
          BED_OK: flow(['off', 62, 64, 66, 68, 70]),
          n: '{{ slot | default(0) | int(0) }}',
          slug: "{{ 'custom_' ~ n }}",
          card: block("{%- set c = state_attr('sensor.moods_custom_' ~ n, 'card') if 1 <= n <= " + SLOTS + " else none %}\n{{ c if c is mapping else {} }}")
        }
      },
      {
        '#': 'Only from inside its own running slot script, after mood_begin made it current,\nnever during vacation, and only for a ready card.',
        condition: 'template',
        value_template: block("{{ 1 <= n <= " + SLOTS + "\n   and is_state('script.mood_' ~ slug, 'on')\n   and states('input_text.house_mood') == slug\n   and not is_state('input_boolean.vacation_mode', 'on')\n   and card.get('mood') == true }}")
      },
      {
        variables: {
          steps: block([
            "{%- set ns = namespace(out=[]) %}",
            "{%- set raw = card.get('mood_steps') %}",
            "{%- for s in (raw if raw is list else [])[:" + STEPS + "] if s is mapping and s.get('lights') in ROLES and s.get('do') in DO %}",
            "  {%- set e = ROLES[s.get('lights')] %}{%- set act = DO[s.get('do')] %}",
            "  {#- a role with no lights yet (or not loaded) is skipped: nothing to send it -#}",
            "  {%- set m = state_attr(e, 'entity_id') %}",
            "  {%- if 'guest_room' not in e and m is iterable and m is not string and m | count > 0 %}",
            "    {%- set ns.out = ns.out + [{'e': e, 'kind': act[0], 'arg': act[1],",
            "                                'pct': [[s.get('pct') | int(0), 1] | max, 100] | min}] %}",
            "  {%- endif %}",
            "{%- endfor %}",
            "{{ ns.out }}"].join('\n')),
          on_steps: "{{ steps | rejectattr('kind', 'eq', 'off') | list }}",
          lit: "{{ expand(on_steps | map(attribute='e') | list) | map(attribute='entity_id') | list }}",
          ex: "{{ card.get('mood_extras') if card.get('mood_extras') is mapping else {} }}",
          fade: "{{ [[ex.get('fade', 2) | int(2), 0] | max, 60] | min }}",
          others_mode: "{{ ex.get('others') if ex.get('others') in ['indoor', 'all'] else 'leave' }}",
          '#': 'The lights to turn off: the leaves of the "off" roles and of the other lights,\nminus every leaf this mood lights (so a lamp in both is never blinked off).',
          to_off: block([
            "{%- set offroles = steps | selectattr('kind', 'eq', 'off') | map(attribute='e') | list %}",
            "{%- set extra = INDOOR if others_mode == 'indoor' else (['light.role_all_lights'] if others_mode == 'all' else []) %}",
            "{{ expand(offroles + extra) | map(attribute='entity_id') | reject('in', lit) | reject('search', 'guest_room') | unique | list }}"].join('\n')),
          tv: "{{ ex.get('tv') if ex.get('tv') in ['on', 'off'] else '' }}",
          scent: "{{ ex.get('scent') if ex.get('scent') in ['on', 'off'] else '' }}",
          bed: "{{ ex.get('bed') if ex.get('bed') in BED_OK else '' }}",
          lit_outdoor: "{{ on_steps | map(attribute='e') | select('in', OUTDOOR) | list | count > 0 }}"
        }
      },
      {
        '#': 'What this run lights outdoors, for the 01:00 outdoor-off (moods_core.yaml): this\nslot\'s slug when an "on" step lit an outdoor role, else empty. It is decided by\nwhat ran, so later edits to the slot, or clearing it, do not change it.',
        action: 'input_text.set_value',
        target: { entity_id: LIT_OUTDOOR },
        data: { value: "{{ slug if lit_outdoor else '' }}" },
        continue_on_error: true
      },
      {
        parallel: [
          {
            sequence: [
              Object.assign(ifThen('{{ to_off | count > 0 }}', [{ action: 'light.turn_off', target: { entity_id: '{{ to_off }}' }, data: { transition: '{{ fade }}' }, continue_on_error: true }])),
              {
                repeat: {
                  for_each: '{{ on_steps }}',
                  sequence: [{
                    choose: [
                      {
                        conditions: "{{ repeat.item.kind == 'white' }}",
                        sequence: [lightOn({ color_temp_kelvin: '{{ [[repeat.item.arg | int(2700), 2000] | max, 6500] | min }}', brightness_pct: '{{ repeat.item.pct }}', transition: '{{ fade }}' })]
                      },
                      {
                        conditions: "{{ repeat.item.kind == 'colour' and repeat.item.arg is list and repeat.item.arg | count == 3 }}",
                        sequence: [lightOn({
                          rgb_color: block("{%- set ns = namespace(c=[]) %}\n{%- for v in repeat.item.arg %}{%- set ns.c = ns.c + [[[v | int(0), 0] | max, 255] | min] %}{%- endfor %}\n{{ ns.c }}"),
                          brightness_pct: '{{ repeat.item.pct }}', transition: '{{ fade }}'
                        })]
                      }
                    ],
                    default: [lightOn({ brightness_pct: '{{ repeat.item.pct }}', transition: '{{ fade }}' })]
                  }]
                }
              }
            ]
          },
          ifThen("{{ tv == 'on' }}", [{ action: 'script.role_bedroom_tv_on', continue_on_error: true }]),
          ifThen("{{ tv == 'off' }}", [{ action: 'script.role_bedroom_tv_off', continue_on_error: true }]),
          ifThen("{{ scent == 'on' }}", [{ action: 'switch.turn_on', target: { entity_id: 'switch.role_diffuser' }, continue_on_error: true }]),
          ifThen("{{ scent == 'off' }}", [{ action: 'switch.turn_off', target: { entity_id: 'switch.role_diffuser' }, continue_on_error: true }]),
          ifThen("{{ bed == 'off' }}", [{ action: 'script.role_bed_off', continue_on_error: true }]),
          ifThen('{{ bed is number }}', [{ '#': 'the wrapper clamps to 60..75 again', action: 'script.role_bed_cool', data: { temperature: '{{ bed }}' }, continue_on_error: true }])
        ]
      }
    ]
  };
}

// the writes of one seed for slot n, grouped by value, every one allowed to fail
function seedWrites(n, sd, withPlacement) {
  const h = helperIds(n);
  const out = [];
  const coe = (x) => Object.assign(x, { continue_on_error: true });
  out.push(coe({ action: 'input_text.set_value', target: { entity_id: h.name }, data: { value: sd.name } }));
  out.push(coe({ action: 'input_text.set_value', target: { entity_id: h.tagline }, data: { value: sd.tagline } }));
  const byOpt = new Map();
  const add = (id, opt) => { if (!byOpt.has(opt)) byOpt.set(opt, []); byOpt.get(opt).push(id); };
  ['glyph', 'colours', 'window', 'fade', 'others', 'tv', 'scent', 'bed'].forEach((k) => add(h[k], sd[k]));
  h.steps.forEach((s, i) => { add(s.lights, sd.steps[i].lights); add(s.do, sd.steps[i].do); });
  if (withPlacement) add(h.where, sd.where);
  byOpt.forEach((ids, opt) => out.push(coe({ action: 'input_select.select_option', target: { entity_id: ids.length === 1 ? ids[0] : ids }, data: { option: opt } })));
  const byNum = new Map();
  h.steps.forEach((s, i) => { const v = sd.steps[i].pct; if (!byNum.has(v)) byNum.set(v, []); byNum.get(v).push(s.pct); });
  if (withPlacement) { if (!byNum.has(sd.order)) byNum.set(sd.order, []); byNum.get(sd.order).push(h.order); }
  byNum.forEach((ids, v) => out.push(coe({ action: 'input_number.set_value', target: { entity_id: ids.length === 1 ? ids[0] : ids }, data: { value: v } })));
  out.push(coe({ action: 'input_boolean.turn_off', target: { entity_id: [h.on, h.night] } }));
  return out;
}
function editorScript(start) {
  const seq = [];
  seq.push({ variables: { n: '{{ slot | default(0) | int(0) }}' } });
  seq.push({
    condition: 'template',
    value_template: start
      ? "{{ n in range(1, " + (SLOTS + 1) + ") and states('sensor.moods_custom_' ~ n) in ['empty', 'unknown', 'unavailable'] }}"
      : '{{ n in range(1, ' + (SLOTS + 1) + ') }}'
  });
  const choose = [];
  for (let n = 1; n <= SLOTS; n++) {
    const writes = seedWrites(n, start ? SEED_START : SEED_CLEAR, true);
    const h = helperIds(n);
    // Start also reads the helpers themselves, so a card that cannot be read (unavailable) never
    // lets it wipe a slot that has a mood in it
    choose.push({ conditions: start ? block("{{ n == " + n + "\n   and (states('" + h.name + "') | replace('|', ' ') | trim) in " + BAD_J + "\n   and not (" + usedExpr(n) + ") }}") : '{{ n == ' + n + ' }}', sequence: writes });
  }
  seq.push({ '#': start ? 'Explicit ids per slot: no entity id is ever built from text. Only a slot with\nnothing in it is filled.' : 'Explicit ids per slot: no entity id is ever built from text.', choose });
  if (!start) {
    seq.push({
      '#': 'Undo must never replay a wiped slot under its old name. The house itself is not changed.',
      if: [{ condition: 'template', value_template: "{{ states('input_text.house_mood_previous') == 'custom_' ~ n }}" }],
      then: [{ action: 'input_text.set_value', target: { entity_id: 'input_text.house_mood_previous' }, data: { value: '' }, continue_on_error: true }]
    });
  }
  seq.push({ action: 'homeassistant.save_persistent_states', continue_on_error: true });
  return start ? {
    alias: 'Moods: start a custom mood',
    description: 'Fills an empty custom mood slot with a draft ("New mood", switched off). Does nothing to a slot that is in use.',
    icon: 'mdi:plus-circle-outline',
    mode: 'single',
    fields: { slot: { name: 'Slot', required: true, selector: { number: { min: 1, max: SLOTS } } } },
    sequence: seq
  } : {
    alias: 'Moods: clear a custom mood',
    description: "Wipes a custom mood slot: its name, card, steps and placement. The house is not changed. Does nothing without a valid slot.",
    icon: 'mdi:delete-outline',
    mode: 'single',
    fields: { slot: { name: 'Slot', required: true, selector: { number: { min: 1, max: SLOTS } } } },
    sequence: seq
  };
}

function saveTriggers() {
  const ids = [];
  for (let n = 1; n <= SLOTS; n++) ids.push('sensor.moods_custom_' + n);
  BUILTIN_SLUGS.concat(Array.from({ length: SLOTS }, (_, i) => 'custom_' + (i + 1))).forEach((s) => { ids.push('input_select.moods_' + s + '_where'); ids.push('input_number.moods_' + s + '_order'); });
  return ids;
}

function packageYaml() {
  const ib = {}, it = {}, is = {}, inum = {}, cust = {}, scripts = {};
  for (let n = 1; n <= SLOTS; n++) {
    const h = helpersFor(n);
    Object.assign(ib, h.ib); Object.assign(it, h.it); Object.assign(is, h.is); Object.assign(inum, h.inum);
    cust['script.mood_custom_' + n] = { mood_slot: n, mood_holds_outdoor: false };
    scripts['mood_custom_' + n] = slotScript(n);
  }
  it['#'] = 'Written only by script.moods_custom_run: the slug of the custom mood whose last run\nlit an outdoor role, or empty. The 01:00 outdoor-off reads it (moods_core.yaml).';
  it[LIT_OUTDOOR.replace('input_text.', '')] = { name: 'Custom moods: lit the outdoors', icon: 'mdi:outdoor-lamp', max: 64 };
  scripts.moods_custom_run = runner();
  scripts.moods_custom_start = editorScript(true);
  scripts.moods_custom_clear = editorScript(false);
  const sensors = [];
  for (let n = 1; n <= SLOTS; n++) sensors.push(sensorFor(n));
  const parts = [HEADER, ''];
  parts.push.apply(parts, emit({ input_boolean: ib }, 0)); parts.push('');
  parts.push.apply(parts, emit({ input_text: it }, 0)); parts.push('');
  parts.push('# Options are frozen in ui/dev/custom-options.lock.json: append, never rename.');
  parts.push.apply(parts, emit({ input_select: is }, 0)); parts.push('');
  parts.push.apply(parts, emit({ input_number: inum }, 0)); parts.push('');
  parts.push('# NOT mood: true. Old phone builds, and anything else that lists mood: true');
  parts.push('# scripts, never see a slot; the new phones read mood_slot and the card sensor.');
  parts.push('# A custom mood never holds the outdoor lights past 22:30.');
  parts.push.apply(parts, emit({ homeassistant: { customize: cust } }, 0)); parts.push('');
  parts.push('# No entity-level variables: on these sensors (Home Assistant renders those once,');
  parts.push('# when tracking starts), so the card body is written out in full twice.');
  parts.push.apply(parts, emit({ template: [{ sensor: sensors }] }, 0)); parts.push('');
  parts.push.apply(parts, emit({ script: scripts }, 0)); parts.push('');
  parts.push.apply(parts, emit({
    automation: [{
      id: 'moods_custom_save_soon',
      alias: 'Moods: save dashboard moods soon after an edit',
      description: 'Dashboard edits are plain helper writes; this makes them survive a crash within seconds instead of 15 minutes.',
      mode: 'restart',
      triggers: [{ '#': "The card sensors change with every slot helper (a state trigger with no `to:`\nalso fires on attribute changes), plus every mood's placement helpers.", trigger: 'state', entity_id: saveTriggers() }],
      conditions: [{ condition: 'template', value_template: "{{ trigger.from_state is not none and trigger.from_state.state not in ['unknown', 'unavailable'] }}" }],
      actions: [{ delay: { seconds: 10 } }, { action: 'homeassistant.save_persistent_states', continue_on_error: true }]
    }]
  }, 0));
  return parts.join('\n') + '\n';
}

/* ---- the six dashboard subviews ------------------------------------------------------------ */
// The usual deck on each phone, as the phones sort it (ui/moods.js fromStates): this phone's own
// moods (mood_panels) by mood_order, then the rest by mood_order, then the custom moods (their
// mood_panels is empty). A change in a mood file changes this text, and lint then asks for --write.
function usualOrders() {
  const l = loadMoods(PKG).map((m) => ({ o: Number(m.attributes.mood_order), name: String(m.attributes.mood_name || m.entity_id), panels: Array.isArray(m.attributes.mood_panels) ? m.attributes.mood_panels.map((x) => String(x).toLowerCase()) : [] }))
    .filter((x) => isFinite(x.o)).sort((a, b) => a.o - b.o || (a.name < b.name ? -1 : 1));
  const fmt = (a) => a.map((x) => x.name + ' ' + x.o).join(', ');
  return WHERE.map((t) => /^Only on the (.+) Palm$/.exec(t)).filter(Boolean).map((m) => {
    const key = m[1].toLowerCase().replace(/[^a-z0-9_]+/g, '_');
    const own = l.filter((x) => x.panels.indexOf(key) >= 0), rest = l.filter((x) => x.panels.indexOf(key) < 0);
    return '**' + m[1] + ' Palm:** ' + fmt(own) + (rest.length ? '; then ' + fmt(rest) : '') + '; then the custom moods, ' + (100 + 10) + ' (slot 1) to ' + (100 + 10 * SLOTS) + ' (slot ' + SLOTS + ').';
  }).join('\n\n');
}
function statusMarkdown(n) {
  const icons = jflow(GLYPH_ICON);
  return [
    "{%- set c = state_attr('sensor.moods_custom_" + n + "', 'card') %}",
    "{%- if c is not mapping %}",
    "This mood's card cannot be read right now. The phones keep showing what they had, and asking for this mood is refused until it can be read.",
    "{%- else %}",
    "{%- set ICON = " + icons + " %}",
    "{%- set pal = c.get('mood_palette') if c.get('mood_palette') is mapping else {} %}",
    "{%- set w = c.get('mood_window') %}",
    "{%- set probs = c.get('mood_problems') if c.get('mood_problems') is list else [] %}",
    "{%- set g = pal.get('glows') if pal.get('glows') is list else [] %}",
    "## <ha-icon icon=\"{{ ICON.get(c.get('mood_glyph'), 'mdi:fire') }}\"></ha-icon> {{ c.get('mood_name') }}",
    "{%- if c.get('mood_state') == 'ready' %}",
    "**Ready.** It shows on the phones (as Where it shows allows) and under Set a mood.",
    "{%- else %}",
    "**Not ready.** {{ c.get('mood_reason') }}{% if not is_state('input_boolean.custom_mood_" + n + "_on', 'on') %} Turn on Switched on, just below, to make it ready.{% endif %}",
    "{%- endif %}",
    "{%- if is_state('input_text.house_mood', 'custom_" + n + "') %}",
    "",
    "**It is the house's mood now.** Undo, below, goes back to the mood before.",
    "{%- endif %}",
    "",
    "**Card:** {{ c.get('mood_tagline') }}",
    "",
    "**Does:** {{ (c.get('mood_summary') ~ '.') if c.get('mood_summary') else 'nothing yet.' }}",
    "{%- if w is mapping %} Runs only from {{ w.get('from') }} to {{ w.get('to') }}.{% else %} Runs at any time.{% endif %}",
    "{%- for p in probs %}",
    "- {{ p }}",
    "{%- endfor %}",
    "",
    "{% for col in [pal.get('base')] + g + [pal.get('accent')] if col is string %}<font color=\"{{ col }}\">■</font>{% endfor %} {{ states('input_select.custom_mood_" + n + "_colours') }}",
    "{%- endif %}"
  ].join('\n');
}
function subview(n) {
  const h = helperIds(n);
  const S = h.sensor;
  const notEmpty = [{ condition: 'state', entity: S, state_not: 'empty' }];
  const sel = (entity, name, icon) => ({ type: 'tile', entity, name, icon, hide_state: true, features_position: 'bottom', features: [{ type: 'select-options' }], grid_options: { columns: 12 } });
  const stepCard = (k) => {
    const s = h.steps[k - 1];
    return {
      type: 'entities', title: 'Step ' + k, show_header_toggle: false,
      entities: [
        { entity: s.lights, name: 'Lights' },
        { type: 'conditional', conditions: [{ entity: s.lights, state_not: NO_STEP }], row: { entity: s.do, name: 'Make them' } },
        { type: 'conditional', conditions: [{ entity: s.lights, state_not: NO_STEP }, { entity: s.do, state_not: 'Off' }], row: { entity: s.pct, name: 'Brightness' } }
      ]
    };
  };
  // (Home Assistant cannot put the mood's name in a confirmation or a page title: both are fixed text)
  const tryAction = { action: 'perform-action', perform_action: 'script.turn_on', target: { entity_id: h.script }, confirmation: { text: 'Set the house to the mood in slot ' + n + ' now? It does what the card above says. Undo (on this page, the Moods tab and the phones) goes back.' } };
  const clearAction = { action: 'perform-action', perform_action: 'script.moods_custom_clear', data: { slot: n }, confirmation: { text: 'Clear the mood in slot ' + n + '? Its name, card text, steps and where it shows are wiped and cannot be brought back. If it is the house\'s mood now, the lights stay as they are.' } };
  const undoAction = { action: 'perform-action', perform_action: 'script.turn_on', target: { entity_id: 'script.mood_undo' }, confirmation: { text: 'Go back to the mood before this one?' } };
  return {
    title: 'Custom mood ' + n,
    path: 'custom-' + n,
    subview: true,
    back_path: '/palm-moods/my-moods',
    type: 'sections',
    max_columns: 3,
    sections: [
      {
        type: 'grid',
        visibility: [{ condition: 'state', entity: S, state: 'empty' }],
        cards: [
          { type: 'heading', heading: 'Custom mood ' + n, heading_style: 'title', icon: 'mdi:palette-swatch-outline' },
          { type: 'markdown', text_only: true, content: 'This slot is empty. Start it to get a draft called "New mood" that lights the bedroom lamps soft white at 40%. It stays switched off, and off the phones, until you switch it on.' },
          { type: 'button', name: 'Start this mood', icon: 'mdi:plus-circle-outline', show_state: false, tap_action: { action: 'perform-action', perform_action: 'script.moods_custom_start', data: { slot: n } }, hold_action: { action: 'none' }, grid_options: { columns: 12 } }
        ]
      },
      {
        type: 'grid',
        visibility: notEmpty,
        cards: [
          { type: 'heading', heading: 'Card', heading_style: 'title', icon: 'mdi:card-text-outline' },
          { type: 'markdown', text_only: true, content: block(statusMarkdown(n)) },
          {
            type: 'entities', show_header_toggle: false,
            entities: [
              { entity: h.on, name: 'Switched on' },
              { entity: h.name, name: 'Name' },
              { entity: h.tagline, name: 'Card text' },
              { entity: h.night, name: 'Night face, like Lights Out' }
            ]
          },
          { type: 'markdown', text_only: true, content: 'Card text: leave it empty to use the summary of what it does. If you write your own, say only what it does.' },
          sel(h.glyph, 'Picture', 'mdi:shape-outline'),
          sel(h.colours, 'Colours', 'mdi:palette'),
          sel(h.window, 'When it runs', 'mdi:clock-outline'),
          {
            type: 'button', name: 'Try it now', icon: 'mdi:play-circle-outline', show_state: false,
            visibility: [{ condition: 'state', entity: S, state: 'ready' }],
            tap_action: tryAction, icon_tap_action: tryAction, hold_action: { action: 'none' }, grid_options: { columns: 6 }
          },
          {
            type: 'tile', entity: 'script.mood_undo', name: 'Undo (back to the mood before)', icon: 'mdi:undo-variant', hide_state: true, vertical: false,
            visibility: [{ condition: 'state', entity: 'input_text.house_mood', state: h.slug }, { condition: 'state', entity: 'input_text.house_mood_previous', state_not: '' }],
            tap_action: undoAction, icon_tap_action: undoAction, hold_action: { action: 'none' }, grid_options: { columns: 6 }
          },
          {
            type: 'markdown', text_only: true,
            visibility: [{ condition: 'state', entity: S, state: 'not_ready' }, { condition: 'state', entity: h.on, state: 'off' }],
            content: 'Try it now appears once Switched on is on. Switched on also puts it on the phones, unless Where it shows (at the bottom of this page) says Hidden on every phone. Once you try it, it is the house\'s mood, and a phone always shows the house\'s mood until another one is set.'
          },
          { type: 'button', name: 'Clear this mood', icon: 'mdi:delete-outline', show_state: false, tap_action: clearAction, icon_tap_action: clearAction, hold_action: { action: 'none' }, grid_options: { columns: 6 } }
        ]
      },
      {
        type: 'grid',
        visibility: notEmpty,
        cards: [{ type: 'heading', heading: 'What it does', heading_style: 'title', icon: 'mdi:lightbulb-group-outline' }]
          .concat([1, 2, 3, 4].slice(0, STEPS).map(stepCard))
          .concat([
            {
              type: 'entities', title: 'Then', show_header_toggle: false,
              entities: [
                { entity: h.others, name: 'Other lights' },
                { entity: h.fade, name: 'Fade' },
                { entity: h.tv, name: 'Bedroom TV' },
                { entity: h.scent, name: 'Diffuser' },
                { entity: h.bed, name: "The bed" }
              ]
            },
            {
              type: 'markdown', text_only: true,
              content: block([
                '**Always true for a custom mood:**',
                '- it never touches the guest room;',
                '- the bed is only ever set between 60 and 75 °F;',
                '- outdoor lights it turns on go off at 01:00 if it is still the mood;',
                '- with a slow fade, the phone does not wait for lights to go off;',
                '- a light in a step that is on is never turned off by another step or by Other lights.'
              ].join('\n'))
            }
          ])
      },
      {
        type: 'grid',
        visibility: notEmpty,
        cards: [
          { type: 'heading', heading: 'Where it shows', heading_style: 'title', icon: 'mdi:cellphone-cog' },
          sel(h.where, 'On the phones', 'mdi:cellphone-cog'),
          { type: 'entities', show_header_toggle: false, entities: [{ entity: h.order, name: 'Order in the deck (0 = usual)' }] },
          {
            type: 'markdown', text_only: true,
            content: block([
              'Each phone shows its moods in three groups: those set to "First on every phone", then that phone\'s own moods, then the rest. The order number sorts a mood only inside its group (0 keeps its usual number). A custom mood is always in the last group, unless Where it shows says "First on every phone", or "Only on" that Palm, which puts it with that phone\'s own moods. For a custom mood, "Usual" means every phone, in the last group.',
              '',
              'The usual decks:',
              '',
              usualOrders(),
              '',
              'Hiding and the order need the Moods app 0.2.0 or newer on the phone; a phone on 0.1.0 shows no custom moods at all. A hidden mood can still be set here, by voice (as "Mood: Custom ' + n + '") and by Undo.'
            ].join('\n'))
          }
        ]
      }
    ]
  };
}
function dashboardBlock() {
  const views = [];
  for (let n = 1; n <= SLOTS; n++) views.push(subview(n));
  const lines = [MARK_START, '  # Do not edit between these markers: change ui/dev/gen-custom.js and run', '  # `node ui/dev/gen-custom.js --write` (lint.js checks they match).'];
  lines.push.apply(lines, emitList(views, 2));
  lines.push(MARK_END);
  return lines.join('\n');
}
// the dashboard text with its generated block replaced (throws if the markers are missing)
function dashboardWith(text) {
  const a = text.indexOf(MARK_START + '\n'), b = text.indexOf('\n' + MARK_END + '\n');
  if (a < 0 || b < 0 || b < a) throw new Error('gen-custom: the marker lines are missing from ' + path.relative(ROOT, DASH_FILE));
  return text.slice(0, a) + dashboardBlock() + text.slice(b + MARK_END.length + 1);
}

/* ---- compare / write ----------------------------------------------------------------------- */
function firstDiff(a, b) {
  const A = a.split('\n'), B = b.split('\n');
  for (let i = 0; i < Math.max(A.length, B.length); i++) if (A[i] !== B[i]) return 'line ' + (i + 1) + '\n    have: ' + JSON.stringify(A[i]) + '\n    want: ' + JSON.stringify(B[i]);
  return '';
}
// -> [] when both files are what this writes, else one message per file
function check() {
  const out = [];
  const pkg = packageYaml();
  const have = fs.existsSync(PKG_FILE) ? fs.readFileSync(PKG_FILE, 'utf8') : '';
  if (have !== pkg) out.push(path.relative(ROOT, PKG_FILE) + ' differs from gen-custom.js: ' + (have ? firstDiff(have, pkg) : 'missing'));
  const dash = fs.readFileSync(DASH_FILE, 'utf8');
  try { const want = dashboardWith(dash); if (want !== dash) out.push(path.relative(ROOT, DASH_FILE) + ' generated block differs from gen-custom.js: ' + firstDiff(dash, want)); } catch (e) { out.push(e.message); }
  return out;
}

module.exports = { SLOTS, STEPS, TABLES, WHERE, SEED_START, SEED_CLEAR, BUILTIN_SLUGS, helperIds, options, packageYaml, dashboardBlock, dashboardWith, check, cardBody, MARK_START, MARK_END, PKG_FILE, DASH_FILE };

if (require.main === module) {
  if (process.argv.includes('--write')) {
    fs.writeFileSync(PKG_FILE, packageYaml());
    fs.writeFileSync(DASH_FILE, dashboardWith(fs.readFileSync(DASH_FILE, 'utf8')));
    console.log('wrote ' + path.relative(ROOT, PKG_FILE) + ' and the generated block of ' + path.relative(ROOT, DASH_FILE));
  } else {
    const d = check();
    d.forEach((m) => console.log('DIFFERS ' + m));
    if (!d.length) console.log('same: ' + path.relative(ROOT, PKG_FILE) + ' and the generated block of ' + path.relative(ROOT, DASH_FILE));
    process.exit(d.length ? 1 : 0);
  }
}
